        CultEvent.Random("sm10", StatId.FollowerFaith, new Question("세례 물에 독 한 방울을 섞어야 진짜 신도가 된다는 말이 젊은 신도들 사이에 돕니다.\u001FYoung followers whisper that a drop of poison in the baptismal water makes a true believer.",
