        CultEvent.Conditional("smeve", c => EyeRules.ReadyToAscend(EyeSector.Samael), new Question("눈먼 신이 처음으로 눈을 뜨려 합니다. 그 눈이 열리기 전에 왕좌에 올라야 합니다. 아이온 트리에서 마지막 걸음만 남았습니다.\u001FThe blind god is trying to open his eyes for the first time. You must take the throne before they open. Only the last step on the Aeon Tree remains.",
                new Choice("신도들을 모두 불러 모은다\u001FGather all the faithful", new Outcome("왕좌 앞에 선 당신 뒤로 신도들의 숨소리가 이어집니다.\u001FBehind you at the throne, the breathing of the faithful stretches on.").C(StatId.Followers, 20).C(StatId.FollowerFaith, 30)),
                new Choice("홀로 왕좌 앞에 선다\u001FStand before the throne alone", new Outcome("혼자라는 것이 오히려 당신을 가볍게 합니다.\u001FBeing alone only makes you lighter.").P(PersonalStatId.Health, 5).P(PersonalStatId.Mentality, 5).C(StatId.LeaderFaith, 20)))),
        CultEvent.Conditional("ydeve", c => EyeRules.ReadyToAscend(EyeSector.Yaldabaoth), new Question("사자의 포효가 물질 세계를 흔듭니다. 흙으로 빚은 모든 것이 새 주인의 이름을 기다립니다. 아이온 트리에서 마지막 걸음만 남았습니다.\u001FThe lion's roar shakes the material world. Everything molded from clay awaits its new master's name. Only the last step on the Aeon Tree remains.",
                new Choice("신도들을 모두 불러 모은다\u001FGather all the faithful", new Outcome("왕좌 앞에 선 당신 뒤로 신도들의 숨소리가 이어집니다.\u001FBehind you at the throne, the breathing of the faithful stretches on.").C(StatId.Followers, 20).C(StatId.FollowerFaith, 30)),
                new Choice("홀로 왕좌 앞에 선다\u001FStand before the throne alone", new Outcome("혼자라는 것이 오히려 당신을 가볍게 합니다.\u001FBeing alone only makes you lighter.").P(PersonalStatId.Health, 5).P(PersonalStatId.Mentality, 5).C(StatId.LeaderFaith, 20)))),
        CultEvent.Conditional("eyerev", c => EyeRules.Reversed, new Question("그노시스를 얻은 뒤 세상이 다르게 보입니다. 사람들이 미덕이라 부르던 것은 거짓 신이 채운 족쇄였고, 욕망이라 부르던 것은 갇힌 빛의 몸부림이었습니다. 이제부터 세상은 거울처럼 뒤집혀 보입니다.\u001FSince gaining Gnosis, the world looks different. What people called virtue was a shackle forged by the false god; what they called desire was the struggle of imprisoned light. From now on, the world appears reversed, as in a mirror.",
                new Choice("뒤집힌 세상을 받아들인다\u001FAccept the reversed world", new Outcome("당신의 눈에 비친 세상이 조용히 뒤집힙니다.\u001FThe world in your eyes quietly turns over.").P(PersonalStatId.Lust, 2).P(PersonalStatId.Greed, 2).P(PersonalStatId.Appetite, 2).P(PersonalStatId.Ambition, 2)),
